import sys

def find(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def is_cyclic_with_edge_removal(n, edges):
    for i in range(len(edges)):
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        cycle = False
        for j, (u, v) in enumerate(edges):
            if i == j:
                continue
            x = find(parent, u)
            y = find(parent, v)
            if x == y:
                cycle = True
                break
            union(parent, rank, x, y)
        if not cycle:
            return True
    return False

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    edges = []
    for _ in range(m):
        u = int(input[index])
        v = int(input[index + 1])
        edges.append((u, v))
        index += 2
    if is_cyclic_with_edge_removal(n, edges):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
